    queue[job_id] = {
        'jobId': job_id,
        'type': body.type,
        'data': body.data,
        'status': 'pending',
        'createdAt': datetime.now().isoformat()
    }
    return {'jobId': job_id}

@app.get('/queue/{job_id}/status')
def get_status(job_id: str):
    job = queue.get(job_id)
    if not job:
        from fastapi.responses import JSONResponse
        return JSONResponse(status_code=404, content={'error': 'Job not found'})
    return {'jobId': job['jobId'], 'status': job['status']}

@app.get('/queue/worker/next')
def next_job():
    for j in queue.values():
        if j['status'] == 'pending':
            j['status'] = 'processing'
            return j
    return {'message': 'No pending jobs'}

@app.post('/queue/worker/{job_id}/complete')
def complete_job(job_id: str):
    job = queue.get(job_id)
    if not job:
        from fastapi.responses import JSONResponse
        return JSONResponse(status_code=404, content={'error': 'Job not found'})
    job['status'] = 'done'
    return {'jobId': job['jobId'], 'status': 'done'}

