package main

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"net/http"
	"os"
	"strings"
	"sync"
	"time"
)

type Job struct {
	JobID     string      `json:"jobId"`
	Type      string      `json:"type"`
	Data      interface{} `json:"data"`
	Status    string      `json:"status"`
	CreatedAt time.Time   `json:"createdAt"`
}

var (
	queue = make(map[string]*Job)
	mu    sync.RWMutex
)

func generateID() string {
	bytes := make([]byte, 16)
	rand.Read(bytes)
	return hex.EncodeToString(bytes)
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	http.HandleFunc("/queue", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method == "POST" {
			var body struct {
				Type string      `json:"type"`
				Data interface{} `json:"data"`
			}
			json.NewDecoder(r.Body).Decode(&body)
			if body.Type == "" {
				w.WriteHeader(http.StatusBadRequest)
				json.NewEncoder(w).Encode(map[string]string{"error": "Type is required"})
				return
			}
			jobID := generateID()
			mu.Lock()
			queue[jobID] = &Job{JobID: jobID, Type: body.Type, Data: body.Data, Status: "pending", CreatedAt: time.Now()}
			mu.Unlock()
			w.WriteHeader(http.StatusCreated)
			json.NewEncoder(w).Encode(map[string]string{"jobId": jobID})
		}
	})

	http.HandleFunc("/queue/", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		path := strings.TrimPrefix(r.URL.Path, "/queue/")
		parts := strings.Split(path, "/")

		if parts[0] == "stats" {
			mu.RLock()
			total := len(queue)
			pending, processing, done := 0, 0, 0
			for _, j := range queue {
				switch j.Status {
				case "pending":
					pending++
				case "processing":
					processing++
				case "done":
					done++
				}
			}
			mu.RUnlock()
			json.NewEncoder(w).Encode(map[string]int{
				"total":      total,
				"pending":    pending,
				"processing": processing,
				"done":       done,
			})
			return
		}

		if len(parts) == 3 && parts[0] == "worker" && parts[2] == "complete" {
			jobID := parts[1]
			mu.Lock()
			job, ok := queue[jobID]
			if !ok {
				mu.Unlock()
				w.WriteHeader(http.StatusNotFound)
				json.NewEncoder(w).Encode(map[string]string{"error": "Job not found"})
				return
			}
			job.Status = "done"
			mu.Unlock()
			json.NewEncoder(w).Encode(map[string]string{"jobId": job.JobID, "status": "done"})
			return
		}

		if parts[0] == "worker" && len(parts) == 2 && parts[1] == "next" {
			mu.Lock()
			var pendingJob *Job
			for _, j := range queue {
				if j.Status == "pending" {
					pendingJob = j
					break
				}
			}
			if pendingJob == nil {
				mu.Unlock()
				json.NewEncoder(w).Encode(map[string]string{"message": "No pending jobs"})
				return
			}
			pendingJob.Status = "processing"
			mu.Unlock()
			json.NewEncoder(w).Encode(pendingJob)
			return
		}

		if len(parts) == 2 && parts[1] == "status" {
			jobID := parts[0]
			mu.RLock()
			job, ok := queue[jobID]
			mu.RUnlock()
			if !ok {
				w.WriteHeader(http.StatusNotFound)
				json.NewEncoder(w).Encode(map[string]string{"error": "Job not found"})
				return
			}
			json.NewEncoder(w).Encode(map[string]string{"jobId": job.JobID, "status": job.Status})
		}
	})

	http.ListenAndServe(":"+port, nil)
}
